1	import { PROVIDER_OPENAI } from './constants.js';
2	import { createOpenAIProvider } from './openai.js';
3	
4	const registry = new Map([[PROVIDER_OPENAI, createOpenAIProvider]]);
5	
6	export function registerProvider(id, factory) {
7	  if (!id || typeof id !== 'string') {
8	    throw new Error('Provider id must be a non-empty string');
9	  }
10	  if (typeof factory !== 'function') {
11	    throw new Error('Provider factory must be a function');
12	  }
13	  registry.set(id, factory);
14	}
15	
16	export function createProvider({ provider = PROVIDER_OPENAI, ...options } = {}) {
17	  const factory = registry.get(provider);
18	  if (!factory) {
19	    throw new Error(`Unknown provider "${provider}"`);
20	  }
21	  return factory(options);
22	}
23	
24	export { PROVIDER_OPENAI, createOpenAIProvider };
