1	import crypto from 'crypto';
2	import fs from 'fs';
3	import path from 'path';
4	
5	import { DEFAULT_CHUNK_SIZE, DEFAULT_INPUT_EXTENSIONS, DEFAULT_VECTOR_FILENAME } from './constants.js';
6	
7	const defaultFs = fs;
8	
9	const normalizeArray = (value) => (Array.isArray(value) ? value : [value]);
10	
11	const safeReadDir = (fsModule, dir) => {
12	  try {
13	    return fsModule.readdirSync(dir);
14	  } catch (error) {
15	    throw new Error(`Unable to read directory "${dir}": ${error.message}`);
16	  }
17	};
18	
19	const safeStat = (fsModule, filePath) => {
20	  try {
21	    return fsModule.statSync(filePath);
22	  } catch (error) {
23	    throw new Error(`Unable to stat "${filePath}": ${error.message}`);
24	  }
25	};
26	
27	const ensureDirectory = (fsModule, targetPath) => {
28	  const dir = path.dirname(targetPath);
29	  if (!fsModule.existsSync(dir)) {
30	    fsModule.mkdirSync(dir, { recursive: true });
31	  }
32	};
33	
34	export function findDocuments(inputPaths, { extensions = DEFAULT_INPUT_EXTENSIONS, fs: fsModule = defaultFs } = {}) {
35	  const sources = normalizeArray(inputPaths ?? process.cwd());
36	  const files = [];
37	
38	  for (const source of sources) {
39	    const absolute = path.resolve(source);
40	    const stats = safeStat(fsModule, absolute);
41	    if (stats.isDirectory()) {
42	      const entries = safeReadDir(fsModule, absolute);
43	      for (const entry of entries) {
44	        const entryPath = path.join(absolute, entry);
45	        const entryStats = safeStat(fsModule, entryPath);
46	        if (entryStats.isDirectory()) {
47	          files.push(...findDocuments(entryPath, { extensions, fs: fsModule }));
48	        } else if (extensions.includes(path.extname(entry).toLowerCase())) {
49	          files.push(entryPath);
50	        }
51	      }
52	    } else if (stats.isFile()) {
53	      if (extensions.includes(path.extname(absolute).toLowerCase())) {
54	        files.push(absolute);
55	      }
56	    }
57	  }
58	
59	  return Array.from(new Set(files)).sort();
60	}
61	
62	export function chunkText(text, { chunkSize = DEFAULT_CHUNK_SIZE } = {}) {
63	  if (!text) return [];
64	  const words = text.split(/\s+/);
65	  const chunks = [];
66	
67	  for (let i = 0; i < words.length; i += chunkSize) {
68	    const chunk = words.slice(i, i + chunkSize).join(' ').trim();
69	    if (chunk.length) {
70	      chunks.push(chunk);
71	    }
72	  }
73	
74	  return chunks;
75	}
76	
77	export function simpleEmbed(text) {
78	  const vector = new Array(8).fill(0);
79	  for (let i = 0; i < text.length; i += 1) {
80	    const code = text.charCodeAt(i);
81	    vector[i % vector.length] += code;
82	  }
83	  const magnitude = Math.sqrt(vector.reduce((sum, value) => sum + value * value, 0)) || 1;
84	  return vector.map((value) => Number((value / magnitude).toFixed(6)));
85	}
86	
87	export function indexDocuments({
88	  input = process.cwd(),
89	  output = path.resolve(DEFAULT_VECTOR_FILENAME),
90	  chunkSize = DEFAULT_CHUNK_SIZE,
91	  extensions = DEFAULT_INPUT_EXTENSIONS,
92	  fs: fsModule = defaultFs,
93	  embed = simpleEmbed,
94	  clock = () => new Date().toISOString()
95	} = {}) {
96	  const sources = findDocuments(input, { extensions, fs: fsModule });
97	
98	  if (!sources.length) {
99	    throw new Error(`No documents found to index for input "${Array.isArray(input) ? input.join(', ') : input}".`);
100	  }
101	
102	  const entries = [];
103	
104	  for (const source of sources) {
105	    const content = fsModule.readFileSync(source, 'utf8');
106	    const chunks = chunkText(content, { chunkSize });
107	    chunks.forEach((chunk, idx) => {
108	      const embedding = embed(chunk);
109	      entries.push({
110	        id: crypto.createHash('sha1').update(`${source}:${idx}`).digest('hex'),
111	        source,
112	        chunkIndex: idx,
113	        chunk,
114	        embedding
115	      });
116	    });
117	  }
118	
119	  const payload = {
120	    metadata: {
121	      createdAt: clock(),
122	      chunkSize,
123	      documentCount: sources.length,
124	      entryCount: entries.length,
125	      input: normalizeArray(input)
126	    },
127	    entries
128	  };
129	
130	  ensureDirectory(fsModule, output);
131	  fsModule.writeFileSync(output, JSON.stringify(payload, null, 2), 'utf8');
132	
133	  return payload;
134	}
135	
136	export default {
137	  findDocuments,
138	  chunkText,
139	  simpleEmbed,
140	  indexDocuments
141	};
