16	describe('config key store', () => {
17	  let tmpCwd;
18	  let tmpHome;
19	
20	  beforeEach(() => {
21	    tmpCwd = fs.mkdtempSync(path.join(os.tmpdir(), 'frai-cwd-'));
22	    tmpHome = fs.mkdtempSync(path.join(os.tmpdir(), 'frai-home-'));
23	  });
24	
25	  afterEach(() => {
26	    fs.rmSync(tmpCwd, { recursive: true, force: true });
27	    fs.rmSync(tmpHome, { recursive: true, force: true });
28	  });
29	
30	  it('handles local env api key lifecycle', () => {
31	    expect(hasLocalApiKey(tmpCwd)).toBe(false);
32	    expect(getLocalApiKey(tmpCwd)).toBeNull();
33	
34	    setLocalApiKey('test-key', tmpCwd);
35	
36	    expect(hasLocalApiKey(tmpCwd)).toBe(true);
37	    expect(getLocalApiKey(tmpCwd)).toBe('test-key');
38	
39	    const envPath = resolveLocalEnvPath(tmpCwd);
40	    const content = fs.readFileSync(envPath, 'utf8');
41	    expect(content).toContain('OPENAI_API_KEY=test-key');
42	  });
43	
44	  it('handles global config api key lifecycle', () => {
45	    expect(hasGlobalApiKey(tmpHome)).toBe(false);
46	    expect(getGlobalApiKey(tmpHome)).toBeNull();
47	
48	    setGlobalApiKey('global-key', tmpHome);
49	
50	    expect(hasGlobalApiKey(tmpHome)).toBe(true);
51	    expect(getGlobalApiKey(tmpHome)).toBe('global-key');
52	
53	    const configPath = resolveGlobalConfigPath(tmpHome);
54	    const content = fs.readFileSync(configPath, 'utf8');
55	    expect(JSON.parse(content).OPENAI_API_KEY).toBe('global-key');
56	  });
57	});
