1	import {
2	  APPROVAL_STATUSES,
3	  DATA_SENSITIVITY_LEVELS,
4	  DEFAULT_GOVERNANCE_TEMPLATE,
5	  GOVERNANCE_SECTIONS,
6	  RISK_LEVELS
7	} from './schema.js';
8	
9	const isPlainObject = (value) => Boolean(value) && typeof value === 'object' && !Array.isArray(value);
10	const asArray = (value) => (Array.isArray(value) ? value : value ? [value] : []);
11	const hasStringValue = (value) => typeof value === 'string' && value.trim().length > 0;
12	
13	const mergeDeep = (target, source) => {
14	  if (!isPlainObject(source)) return source;
15	  const result = Array.isArray(target) ? [...target] : { ...(isPlainObject(target) ? target : {}) };
16	  for (const [key, value] of Object.entries(source)) {
17	    if (Array.isArray(value)) {
18	      result[key] = [...value];
19	    } else if (isPlainObject(value)) {
20	      result[key] = mergeDeep(result[key], value);
21	    } else {
22	      result[key] = value;
23	    }
24	  }
25	  return result;
26	};
27	
28	const ensureSection = (plan, sectionName, errors) => {
29	  const section = plan[sectionName];
30	  if (!isPlainObject(section)) {
31	    errors.push({
32	      path: sectionName,
33	      message: `Section "${sectionName}" is required and must be an object.`
34	    });
35	    return {};
36	  }
37	  return section;
38	};
39	
40	const validateFieldShape = (value, expectedShape) => {
41	  switch (expectedShape) {
42	    case 'string':
43	      return hasStringValue(value);
44	    case 'string[]':
45	      return Array.isArray(value) && value.every(hasStringValue);
46	    case 'object':
47	      return isPlainObject(value);
48	    case 'object[]':
49	      return Array.isArray(value) && value.every(isPlainObject);
50	    default:
51	      return true;
52	  }
53	};
54	
55	const validateStakeholders = (stakeholders) => {
56	  const errors = [];
57	  stakeholders.forEach((stakeholder, index) => {
58	    const prefix = `approvals.stakeholders[${index}]`;
59	    if (!hasStringValue(stakeholder.role)) {
60	      errors.push({ path: `${prefix}.role`, message: 'Role is required.' });
61	    }
62	    if (!hasStringValue(stakeholder.name)) {
63	      errors.push({ path: `${prefix}.name`, message: 'Name is required.' });
64	    }
65	    if (!APPROVAL_STATUSES.includes(stakeholder.status)) {
66	      errors.push({
67	        path: `${prefix}.status`,
68	        message: `Status must be one of: ${APPROVAL_STATUSES.join(', ')}.`
69	      });
70	    }
71	  });
72	  return errors;
73	};
74	
75	const validateDatasetSources = (sources) => {
76	  const errors = [];
77	  sources.forEach((source, index) => {
78	    const prefix = `dataset.sources[${index}]`;
79	    if (!hasStringValue(source.name)) {
80	      errors.push({ path: `${prefix}.name`, message: 'Name is required.' });
81	    }
82	    if (!hasStringValue(source.type)) {
83	      errors.push({ path: `${prefix}.type`, message: 'Type is required.' });
84	    }
85	    if (!hasStringValue(source.access)) {
86	      errors.push({ path: `${prefix}.access`, message: 'Access channel is required.' });
87	    }
88	    if (!hasStringValue(source.owner)) {
89	      errors.push({ path: `${prefix}.owner`, message: 'Owner is required.' });
90	    }
91	  });
92	  return errors;
93	};
94	
95	const validateEvaluationMetrics = (metrics) => {
96	  const errors = [];
97	  metrics.forEach((metric, index) => {
98	    const prefix = `evaluation.metrics[${index}]`;
99	    if (!hasStringValue(metric.name)) {
100	      errors.push({ path: `${prefix}.name`, message: 'Metric name is required.' });
101	    }
102	    if (!hasStringValue(metric.direction)) {
103	      errors.push({
104	        path: `${prefix}.direction`,
105	        message: 'Metric direction (increase/decrease/maintain) is required.'
106	      });
107	    }
108	    if (typeof metric.threshold !== 'number') {
109	      errors.push({
110	        path: `${prefix}.threshold`,
111	        message: 'Metric threshold must be a number.'
112	      });
113	    }
114	  });
115	  return errors;
116	};
117	
118	const validateMonitoringMetrics = (metrics) => {
119	  const errors = [];
120	  metrics.forEach((metric, index) => {
121	    const prefix = `monitoring.metrics[${index}]`;
122	    if (!hasStringValue(metric.name)) {
123	      errors.push({ path: `${prefix}.name`, message: 'Metric name is required.' });
124	    }
125	    if (!hasStringValue(metric.alertCondition)) {
126	      errors.push({
127	        path: `${prefix}.alertCondition`,
128	        message: 'Alert condition is required.'
129	      });
130	    }
131	    if (!hasStringValue(metric.owner)) {
132	      errors.push({ path: `${prefix}.owner`, message: 'On-call owner is required.' });
133	    }
134	  });
135	  return errors;
136	};
137	
138	export function createGovernanceTemplate(overrides = {}) {
139	  return mergeDeep(DEFAULT_GOVERNANCE_TEMPLATE, overrides);
140	}
141	
142	export function validateGovernancePlan(plan) {
143	  const errors = [];
144	
145	  if (!isPlainObject(plan)) {
146	    return {
147	      valid: false,
148	      errors: [{ path: '', message: 'Governance plan must be an object.' }]
149	    };
150	  }
151	
152	  for (const [sectionName, sectionDef] of Object.entries(GOVERNANCE_SECTIONS)) {
153	    const section = ensureSection(plan, sectionName, errors);
154	    if (!isPlainObject(section)) continue;
155	
156	    for (const requiredField of sectionDef.requiredFields) {
157	      if (section[requiredField] === undefined || section[requiredField] === null) {
158	        errors.push({
159	          path: `${sectionName}.${requiredField}`,
160	          message: `Field "${requiredField}" is required in section "${sectionName}".`
161	        });
162	      }
163	    }
164	
165	    for (const [fieldName, expectedShape] of Object.entries(sectionDef.fieldShapes)) {
166	      const value = section[fieldName];
167	      if (value === undefined || value === null) continue;
168	      if (!validateFieldShape(value, expectedShape)) {
169	        errors.push({
170	          path: `${sectionName}.${fieldName}`,
171	          message: `Field "${fieldName}" in section "${sectionName}" must match shape "${expectedShape}".`
172	        });
173	      }
174	    }
175	  }
176	
177	  const dataset = plan.dataset ?? {};
178	  if (dataset.sensitivity) {
179	    if (!DATA_SENSITIVITY_LEVELS.includes(dataset.sensitivity.level)) {
180	      errors.push({
181	        path: 'dataset.sensitivity.level',
182	        message: `Sensitivity level must be one of: ${DATA_SENSITIVITY_LEVELS.join(', ')}.`
183	      });
184	    }
185	    if (typeof dataset.sensitivity.piiPresent !== 'boolean') {
186	      errors.push({
187	        path: 'dataset.sensitivity.piiPresent',
188	        message: 'PII presence flag must be a boolean.'
189	      });
190	    }
191	  }
192	
193	  if (dataset.sources) {
194	    errors.push(...validateDatasetSources(asArray(dataset.sources)));
195	  }
196	
197	  const training = plan.training ?? {};
198	  if (training.safety && Array.isArray(training.safety.guardrails)) {
199	    if (!training.safety.guardrails.every(hasStringValue)) {
200	      errors.push({
201	        path: 'training.safety.guardrails',
202	        message: 'All safety guardrails must be non-empty strings.'
203	      });
204	    }
205	  }
206	
207	  const evaluation = plan.evaluation ?? {};
208	  if (evaluation.metrics) {
209	    errors.push(...validateEvaluationMetrics(asArray(evaluation.metrics)));
210	  }
211	  if (evaluation.gateCriteria) {
212	    if (!RISK_LEVELS.includes(evaluation.gateCriteria.riskTolerance)) {
213	      errors.push({
214	        path: 'evaluation.gateCriteria.riskTolerance',
215	        message: `Risk tolerance must be one of: ${RISK_LEVELS.join(', ')}.`
216	      });
217	    }
218	    if (typeof evaluation.gateCriteria.minimumSuccessRate !== 'number') {
219	      errors.push({
220	        path: 'evaluation.gateCriteria.minimumSuccessRate',
221	        message: 'Minimum success rate must be numeric.'
222	      });
223	    }
224	  }
225	
226	  const approvals = plan.approvals ?? {};
227	  if (Array.isArray(approvals.stakeholders)) {
228	    errors.push(...validateStakeholders(approvals.stakeholders));
229	  } else {
230	    errors.push({
231	      path: 'approvals.stakeholders',
232	      message: 'Stakeholders must be provided as an array.'
233	    });
234	  }
235	
236	  const monitoring = plan.monitoring ?? {};
237	  if (monitoring.metrics) {
238	    errors.push(...validateMonitoringMetrics(asArray(monitoring.metrics)));
239	  }
240	  if (monitoring.rollbackPlan) {
241	    if (!Array.isArray(monitoring.rollbackPlan.steps)) {
242	      errors.push({
243	        path: 'monitoring.rollbackPlan.steps',
244	        message: 'Rollback steps must be an array.'
245	      });
246	    } else if (!monitoring.rollbackPlan.steps.every(hasStringValue)) {
247	      errors.push({
248	        path: 'monitoring.rollbackPlan.steps',
249	        message: 'All rollback steps must be non-empty strings.'
250	      });
251	    }
252	  }
253	
254	  const audit = plan.audit ?? {};
255	  if (audit.artefacts) {
256	    if (!Array.isArray(audit.artefacts)) {
257	      errors.push({
258	        path: 'audit.artefacts',
259	        message: 'Artefacts must be an array of file references.'
260	      });
261	    } else if (!audit.artefacts.every(hasStringValue)) {
262	      errors.push({
263	        path: 'audit.artefacts',
264	        message: 'Artefact entries must be non-empty strings.'
265	      });
266	    }
267	  }
268	
269	  return {
270	    valid: errors.length === 0,
271	    errors
272	  };
273	}
274	
275	export function calculateReadiness(plan) {
276	  const checkpoints = {
277	    dataset: false,
278	    evaluation: false,
279	    approvals: false,
280	    monitoring: false,
281	    audit: false
282	  };
283	
284	  if (isPlainObject(plan.dataset)) {
285	    const { useCases = [], sources = [], qualityChecks = {} } = plan.dataset;
286	    checkpoints.dataset =
287	      useCases.length > 0 &&
288	      sources.length > 0 &&
289	      hasStringValue(qualityChecks.biasAssessment) &&
290	      hasStringValue(qualityChecks.manualReview);
291	  }
292	
293	  if (isPlainObject(plan.evaluation)) {
294	    const { metrics = [], gateCriteria = {} } = plan.evaluation;
295	    checkpoints.evaluation =
296	      metrics.length > 0 &&
297	      metrics.every((metric) => typeof metric.threshold === 'number') &&
298	      typeof gateCriteria.minimumSuccessRate === 'number';
299	  }
300	
301	  if (isPlainObject(plan.approvals) && Array.isArray(plan.approvals.stakeholders)) {
302	    const stakeholders = plan.approvals.stakeholders;
303	    checkpoints.approvals =
304	      stakeholders.length > 0 && stakeholders.every((stakeholder) => stakeholder.status === 'approved');
305	  }
306	
307	  if (isPlainObject(plan.monitoring)) {
308	    const { owner, metrics = [], rollbackPlan = {} } = plan.monitoring;
309	    checkpoints.monitoring =
310	      hasStringValue(owner) &&
311	      metrics.length > 0 &&
312	      hasStringValue(rollbackPlan.trigger) &&
313	      Array.isArray(rollbackPlan.steps) &&
314	      rollbackPlan.steps.length > 0;
315	  }
316	
317	  if (isPlainObject(plan.audit)) {
318	    const { artefacts = [] } = plan.audit;
319	    checkpoints.audit = artefacts.length > 0;
320	  }
321	
322	  const blockers = Object.entries(checkpoints)
323	    .filter(([, complete]) => !complete)
324	    .map(([name]) => name);
325	
326	  let status = 'ready';
327	  if (blockers.length > 0) {
328	    const criticalBlockers = blockers.filter((item) => item === 'evaluation' || item === 'approvals');
329	    status = criticalBlockers.length > 0 ? 'blocked' : 'pending';
330	  }
331	
332	  const completed = Object.values(checkpoints).filter(Boolean).length;
333	  const score = completed / Object.keys(checkpoints).length;
334	
335	  return {
336	    status,
337	    score,
338	    checkpoints
339	  };
340	}
341	
342	export function summarizeGovernance(plan) {
343	  const readiness = calculateReadiness(plan);
344	  const lines = [
345	    `Fine-tuning readiness: ${readiness.status.toUpperCase()} (${Math.round(readiness.score * 100)}% complete)`
346	  ];
347	
348	  const pending = Object.entries(readiness.checkpoints)
349	    .filter(([, complete]) => !complete)
350	    .map(([name]) => name);
351	
352	  if (pending.length) {
353	    lines.push(`Outstanding checkpoints: ${pending.join(', ')}`);
354	  } else {
355	    lines.push('All checkpoints satisfied. Ready for launch.');
356	  }
357	
358	  return lines.join('\n');
359	}
360	
361	export default {
362	  APPROVAL_STATUSES,
363	  DATA_SENSITIVITY_LEVELS,
364	  GOVERNANCE_SECTIONS,
365	  RISK_LEVELS,
366	  createGovernanceTemplate,
367	  validateGovernancePlan,
368	  calculateReadiness,
369	  summarizeGovernance
370	};
