1	import fs from 'fs';
2	import path from 'path';
3	
4	import {
5	  DEFAULT_CODE_EXTENSIONS,
6	  DEFAULT_EXCLUDED_DIRS
7	} from './constants.js';
8	import { DEFAULT_DETECTORS } from './detectors.js';
9	
10	const defaultConfig = {
11	  root: process.cwd(),
12	  excludedDirs: DEFAULT_EXCLUDED_DIRS,
13	  extensions: DEFAULT_CODE_EXTENSIONS,
14	  detectors: DEFAULT_DETECTORS,
15	  fs
16	};
17	
18	const shouldSkip = (name, excluded) => excluded.includes(name);
19	
20	const createResult = () => {
21	  const result = {
22	    aiFiles: [],
23	    totalFiles: 0,
24	    aiLibraryMatches: {},
25	    aiFunctionMatches: {}
26	  };
27	
28	  const aiSet = new Set();
29	  result.markAiFile = (filePath) => {
30	    if (!aiSet.has(filePath)) {
31	      aiSet.add(filePath);
32	      result.aiFiles.push(filePath);
33	    }
34	  };
35	
36	  return result;
37	};
38	
39	export function scanCodebase(options = {}) {
40	  const config = { ...defaultConfig, ...options };
41	  const {
42	    root,
43	    excludedDirs,
44	    extensions,
45	    detectors,
46	    fs: fsModule
47	  } = config;
48	
49	  const result = createResult();
50	
51	  function scanDirectory(dir) {
52	    let entries;
53	    try {
54	      entries = fsModule.readdirSync(dir, { withFileTypes: true });
55	    } catch (error) {
56	      console.error(`Error scanning directory ${dir}: ${error.message}`);
57	      return;
58	    }
59	
60	    for (const entry of entries) {
61	      if (shouldSkip(entry.name, excludedDirs)) continue;
62	
63	      const fullPath = path.join(dir, entry.name);
64	
65	      if (entry.isDirectory()) {
66	        scanDirectory(fullPath);
67	      } else if (entry.isFile()) {
68	        const ext = path.extname(entry.name).toLowerCase();
69	        if (!extensions.includes(ext)) continue;
70	
71	        result.totalFiles += 1;
72	        let content;
73	        try {
74	          content = fsModule.readFileSync(fullPath, 'utf8');
75	        } catch (error) {
76	          console.error(`Error reading file ${fullPath}: ${error.message}`);
77	          continue;
78	        }
79	
80	        for (const detector of detectors) {
81	          try {
82	            detector.analyze({
83	              filePath: fullPath,
84	              content,
85	              result,
86	              config
87	            });
88	          } catch (error) {
89	            console.error(`Detector ${detector.id || 'unknown'} failed on ${fullPath}: ${error.message}`);
90	          }
91	        }
92	      }
93	    }
94	  }
95	
96	  scanDirectory(root);
97	
98	  return {
99	    aiFiles: result.aiFiles,
100	    totalFiles: result.totalFiles,
101	    aiLibraryMatches: result.aiLibraryMatches,
102	    aiFunctionMatches: result.aiFunctionMatches
103	  };
104	}
105	
106	export function createScanner(config = {}) {
107	  return (overrides = {}) => scanCodebase({ ...config, ...overrides });
108	}
