16	export function loadDataset({ outputsPath, referencesPath, fs: fsModule = defaultFs } = {}) {
17	  if (!outputsPath) {
18	    throw new Error('outputsPath is required for evaluation.');
19	  }
20	
21	  const outputsAbsolute = path.resolve(outputsPath);
22	  const outputsRaw = fsModule.readFileSync(outputsAbsolute, 'utf8');
23	  const outputs = JSON.parse(outputsRaw);
24	
25	  let references = [];
26	  let referencesAbsolute = null;
27	  if (referencesPath) {
28	    referencesAbsolute = path.resolve(referencesPath);
29	    const referencesRaw = fsModule.readFileSync(referencesAbsolute, 'utf8');
30	    references = JSON.parse(referencesRaw);
31	  }
32	
33	  return {
34	    outputs,
35	    references,
36	    outputsPath: outputsAbsolute,
37	    referencesPath: referencesAbsolute
38	  };
39	}
