88	  fs: fsModule = defaultFs
89	}) {
90	  const resolved = resolveReportPath(reportPath, format);
91	  const payload = format === 'markdown' ? toMarkdown(report) : toJson(report);
92	  fsModule.writeFileSync(resolved, payload, 'utf8');
93	  return resolved;
94	}
