7	const ensureFetch = (providedFetch) => {
8	  if (typeof providedFetch === 'function') {
9	    return providedFetch;
10	  }
11	  if (typeof globalThis !== 'undefined' && typeof globalThis.fetch === 'function') {
12	    return globalThis.fetch.bind(globalThis);
