28	const buildChatPayload = ({
29	  messages,
30	  model = DEFAULT_OPENAI_CHAT_MODEL,
31	  temperature,
32	  maxTokens,
33	  responseFormat,
34	  seed
35	}) => {
36	  if (!Array.isArray(messages) || messages.length === 0) {
37	    throw new Error('messages array is required for chat completion');
38	  }
39	
40	  const payload = {
41	    model,
42	    messages
43	  };
44	
45	  if (typeof temperature === 'number') {
46	    payload.temperature = temperature;
47	  }
48	
49	  if (typeof maxTokens === 'number') {
50	    payload.max_tokens = maxTokens;
51	  }
52	
53	  if (responseFormat) {
54	    payload.response_format = responseFormat;
55	  }
56	
57	  if (typeof seed === 'number') {
58	    payload.seed = seed;
59	  }
60	
61	  return payload;
62	};
