64	const parseChatResponse = async (response) => {
65	  const json = await response.json();
66	  const choice = json?.choices?.[0];
67	  const content = choice?.message?.content ?? '';
68	
69	  return {
70	    content,
71	    model: json.model ?? null,
72	    usage: json.usage ?? null,
73	    raw: json
74	  };
75	};
76	
77	const parseErrorResponse = async (response) => {
78	  try {
79	    const payload = await response.json();
80	    const message = payload?.error?.message ?? `OpenAI request failed with status ${response.status}`;
81	    const error = new Error(message);
82	    error.status = response.status;
83	    error.payload = payload;
84	    return error;
85	  } catch (error) {
86	    const generic = new Error(`OpenAI request failed with status ${response.status}`);
87	    generic.status = response.status;
88	    return generic;
89	  }
90	};
