92	export function createOpenAIProvider({
93	  apiKey,
94	  baseUrl = DEFAULT_OPENAI_BASE_URL,
95	  organization,
96	  fetch: providedFetch
97	} = {}) {
98	  if (!apiKey) {
99	    throw new Error('OpenAI provider requires an API key');
100	  }
101	
102	  const fetchFn = ensureFetch(providedFetch);
103	  if (!fetchFn) {
104	    throw new Error('OpenAI provider requires a fetch implementation');
105	  }
106	
107	  const headers = buildHeaders({ apiKey, organization });
108	
109	  return {
110	    id: PROVIDER_OPENAI,
111	    async chatCompletion(options) {
112	      const payload = buildChatPayload(options ?? {});
113	      const response = await fetchFn(`${baseUrl}/chat/completions`, {
114	        method: 'POST',
115	        headers,
116	        body: JSON.stringify(payload),
117	        signal: options?.signal
118	      });
119	
120	      if (!response.ok) {
121	        throw await parseErrorResponse(response);
122	      }
123	
124	      return parseChatResponse(response);
125	    }
126	  };
127	}
